cd /home/sfmqrb/git/rishe/data/verification/sources/refs; python3 - <<'EOF'
t=open('KLN_1966.txt',encoding='utf-8',errors='replace').read()
lines=t.split('\n')
for pat in ["amber,  n.","ana-,  pref"]:
    for i,l in enumerate(lines):
        if l.startswith(pat):
            print(pat,'leaf',('\n'.join(lines[:i])).count('\f'))
            break
EOF
echo "=== KLN ana- ==="; grep -n "^ana-,\|^ana,\|^an-,\|^analysis\|^analogy\|^anatomy\|^unless\|^umbrella\|^umbra," KLN_1966.txt | head -20

